import{_ as o,o as a,c as r,a5 as t}from"./chunks/framework.CXvGqWf0.js";const u=JSON.parse('{"title":"漫画 · 第 61 话 零 JS 交互组件：:has() + 锚点定位 + popover + @starting-style","description":"","frontmatter":{},"headers":[],"relativePath":"comics/scenarios/EP.61-zero-js-interactions.md","filePath":"comics/scenarios/EP.61-zero-js-interactions.md","lastUpdated":1793853676000}'),c={name:"comics/scenarios/EP.61-zero-js-interactions.md"};function i(s,e,d,n,l,h){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="漫画-·-第-61-话-零-js-交互组件-has-锚点定位-popover-starting-style" tabindex="-1">漫画 · 第 61 话 零 JS 交互组件：:has() + 锚点定位 + popover + @starting-style <a class="header-anchor" href="#漫画-·-第-61-话-零-js-交互组件-has-锚点定位-popover-starting-style" aria-label="Permalink to &quot;漫画 · 第 61 话 零 JS 交互组件：:has() + 锚点定位 + popover + @starting-style&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/scenarios/02-zero-js-interactions">docs/scenarios/02-zero-js-interactions.md</a> ｜ 原画：<a href="./EP.61-zero-js-interactions.svg">EP.61-zero-js-interactions.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师。本话她花两天写的下拉菜单，一放进表格行就被 <code>overflow:hidden</code> 裁掉。</li><li><strong>标签君</strong>：结构师。负责把“状态、定位、顶层、入场”四件事拆给浏览器原生能力。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>像素酱的菜单用绝对定位 + JS 算坐标，打开时正常，滚动后错位，放进表格行还被裁剪。她试过把 <code>z-index</code> 调到 99999，没用。标签君让她改用 <code>popover</code> 进顶层，用 CSS 锚点定位跟随按钮，用 <code>:has()</code> 驱动按钮状态，用 <code>@starting-style</code> 做淡入。定位与事件代码从 300 行降到 8 行，只剩 aria 同步。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>绝对定位浮层受包含块、<code>overflow</code>、<code>transform</code> 三层约束。JS 只在打开时算一次坐标，滚动与缩放后不更新；祖先一裁，菜单直接消失。<code>z-index</code> 只能解决同层叠顺序，解决不了裁剪上下文。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p><code>popover</code> 把元素送进顶层，脱离祖先裁剪，并自带点击外部关闭、Esc 关闭与焦点管理。CSS 锚点定位在布局阶段解析锚点与目标的位置关系，<code>position-area</code> 描述九宫格方位，<code>position-try-fallbacks</code> 在空间不足时翻转。<code>@starting-style</code> 提供首次渲染的起始值，<code>allow-discrete</code> 让 <code>display</code> 也能过渡。<code>:has()</code> 让祖先根据后代状态改样式。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>组合后的菜单：按钮设 <code>anchor-name</code>，浮层 <code>position-anchor</code> 绑定并 <code>position-area: block-end</code>；打开时通过 <code>:popover-open</code> 与 <code>@starting-style</code> 淡入；<code>.menu-wrap:has(.menu:popover-open)</code> 翻转箭头。滚动跟随、外部关闭、裁剪问题都由平台接管。像素酱保留 8 行 JS 同步 <code>aria-expanded</code>，因为 popover 不自动维护它。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li><code>popover</code> 进顶层，解决裁剪与层叠；但它默认居中，必须重置 <code>margin/inset</code>。</li><li>锚点定位在布局阶段解析，滚动自动跟随，不需要读 <code>getBoundingClientRect</code>。</li><li><code>@starting-style</code> 只管首次渲染帧；关闭动画要 <code>display … allow-discrete</code>。</li><li><code>:has()</code> 让父级感知后代状态，但避免在超大 DOM 上写宽泛条件。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：菜单已经用了 <code>popover</code>，为什么还要写 <code>position-anchor</code> 和 <code>position-area</code>？</p><p><strong>答</strong>：<code>popover</code> 只负责“进顶层 + 开关行为”，不负责“贴住触发按钮”。不写锚点定位时，浮层会按浏览器默认样式居中显示。<code>position-anchor</code> 绑定锚点，<code>position-area</code> 指定放在锚点的哪一侧，二者才让浮层跟随按钮并在空间不足时翻转。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>打开菜单、缩小容器高度、滚动页面，观察顶层与跟随行为：<a href="./../../examples/scenarios/02-zero-js-interactions">examples/scenarios/02-zero-js-interactions</a></li><li>在 DevTools 中查看 <code>#menu</code> 是否位于 top layer，以及 <code>@starting-style</code> 的首帧效果。</li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>单页内不写 JS 了，跨页导航还能连续吗？第 62 话《MPA 级转场》——View Transitions 与 Speculation Rules。</p>',22)])])}const m=o(c,[["render",i]]);export{u as __pageData,m as default};
